import stackprinter

# Test 1: Simple attribute access
def test_simple_attribute():
    class TestObj:
        @property
        def attr(self):
            return "value"

    obj = TestObj()
    try:
        result = obj.attr
        print(f"Simple attribute access: {result}")
    except Exception as e:
        msg = stackprinter.format()
        print(f"Error in simple attribute access: {e}")

