    class InnerObj:
        @property
        def inner_attr(self):
            return "inner_value"

    class OuterObj:
        def __init__(self):
            self.inner = InnerObj()

    obj = OuterObj()
    try:
        result = obj.inner.inner_attr
        print(f"Nested attribute access: {result}")
    except Exception as e:
        msg = stackprinter.format()
        print(f"Error in nested attribute access: {e}")

# Test 4: Failed nested attribute access
