        @property
        def inner_attr(self):
            raise RuntimeError("inner error")

    class OuterObj:
        def __init__(self):
            self.inner = InnerObj()

    obj = OuterObj()
    try:
        result = obj.inner.inner_attr
    except:
        msg = stackprinter.format()
        print("Failed nested attribute access test passed")

# Test 5: Simple variable access (no dots)
