    try:
        result = x
        print(f"Simple variable access: {result}")
    except Exception as e:
        msg = stackprinter.format()
        print(f"Error in simple variable access: {e}")

if __name__ == "__main__":
    test_simple_attribute()
    test_failed_attribute()
    test_nested_attribute()
    test_failed_nested_attribute()
    test_simple_variable()
    print("All tests completed successfully")
EOF
```

